import pickle,numpy as np
m,report=pickle.load(open('molconfs.pkl','rb')); pos=np.array(m.GetConformer(report[0][2]).GetPositions()); b=pos[0];h=pos[31]; bh=(b-h)/np.linalg.norm(b-h); inpos=b+bh*4.15;print('B',b,'H',h,'In',inpos,'BS',np.linalg.norm(pos[[10,20,30]]-b,axis=1),'InS',np.linalg.norm(pos[[10,20,30]]-inpos,axis=1));
with open('initial.xyz','w') as f:
 f.write(f'{m.GetNumAtoms()+1}\nIn(I) hydrotris(tert-butylimidazole-thione)borate\n');
 for atom,p in zip(m.GetAtoms(),pos):f.write(f'{atom.GetSymbol()} {p[0]:.8f} {p[1]:.8f} {p[2]:.8f}\n')
 f.write(f'In {inpos[0]:.8f} {inpos[1]:.8f} {inpos[2]:.8f}\n')
print('num atoms',m.GetNumAtoms()+1)
